// spec: specs/delivery.md §8 · кейс .qa/tests/delivery/dlv-12-drivers-loading-no-empty-flash.md
// seed: tests/seed.admin.spec.ts
// #a8bdcb (עבר QA 25.10): пока грузится список водителей, «עדיין אין נהגים פעילים…» не показывается (ни на кадр);
// показывается только если после загрузки водителей действительно нет.
// Как проверяется: page.route задерживает ответ GET /rest/v1/profiles?…role=eq.driver… на 3 с (ответ не меняется),
// MutationObserver (addInitScript, с начала документа) ловит любое появление фразы. «Нет водителей» — подмена ответа на []
// только в этом окне браузера (сервер не трогаем). Утверждённый заказ клиента «test» берётся динамически. Ничего не сохраняется.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const NO_DRIVERS = 'עדיין אין נהגים פעילים';
const DRIVERS_API = /\/rest\/v1\/profiles\?.*role=eq\.driver/;
const APPROVED_STAGES = ['ממתינה לליקוט', 'בליקוט במחסן', 'מוכנה למשלוח', 'בדרך ללקוח'];

/** Наблюдатель с начала каждого документа: window.__noDriversSeen = true, если фраза хоть раз была в DOM. */
async function watchNoDrivers(page: Page) {
  await page.addInitScript((phrase: string) => {
    const w = window as unknown as { __noDriversSeen?: boolean };
    w.__noDriversSeen = false;
    const check = () => {
      if (!w.__noDriversSeen && (document.body?.textContent || '').includes(phrase)) w.__noDriversSeen = true;
    };
    new MutationObserver(check).observe(document, { childList: true, subtree: true, characterData: true });
  }, NO_DRIVERS);
}
const seen = (page: Page) => page.evaluate(() => (window as unknown as { __noDriversSeen?: boolean }).__noDriversSeen === true);

/** id утверждённого заказа клиента «test» с адресом (карточка без «ללקוח אין כתובת משלוח»). */
async function findApprovedOrderId(page: Page): Promise<string | null> {
  for (const stage of APPROVED_STAGES) {
    await page.goto('/orders');
    await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    await page.getByRole('button', { name: 'סינון' }).click();
    await page.getByRole('combobox', { name: 'שלב ההזמנה' }).selectOption({ label: stage });
    const mine = page.getByRole('button', { name: /^#\d+ test / });
    await expect(mine.first().or(page.getByText('לא נמצאו הזמנות התואמות לסינון'))).toBeVisible({ timeout: 20_000 });
    if (!(await mine.count())) continue;
    await mine.first().click();
    await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
    await expect(page.getByRole('combobox', { name: 'נהג' })).toBeVisible({ timeout: 30_000 });
    if (await page.getByText('ללקוח אין כתובת משלוח').count()) continue;
    return page.url().split('/').pop()!;
  }
  return null;
}

/** Задержать ответ списка водителей на ms (ответ настоящий). Возвращает счётчик перехваченных запросов. */
async function delayDrivers(page: Page, ms: number) {
  const hits = { n: 0 };
  await page.route(DRIVERS_API, async (route) => {
    hits.n++;
    await new Promise((r) => setTimeout(r, ms));
    await route.continue();
  });
  return hits;
}

const SCREENS = [
  { name: 'כרטיס הזמנה', url: (id: string) => `/orders/${id}` },
  { name: 'תעודת משלוח', url: (id: string) => `/delivery/${id}` },
];

test.describe('delivery — «עדיין אין נהגים פעילים» לא מופיע בזמן טעינת הנהגים (#a8bdcb)', () => {
  let orderId: string | null = null;

  test.beforeAll(async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/admin.json'), baseURL: test.info().project.use.baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try {
      orderId = await findApprovedOrderId(await ctx.newPage());
    } finally {
      await ctx.close();
    }
  });

  for (const s of SCREENS) {
    test(`${s.name}: תשובת הנהגים מתעכבת 3 ש' — ההודעה לא מופיעה אף לרגע, אחר כך הרשימה #a8bdcb @desktop @prod-safe`, async ({ page }) => {
      test.skip(!orderId, 'нет утверждённого заказа клиента «test» с адресом');
      await watchNoDrivers(page);
      const hits = await delayDrivers(page, 3000);
      await page.goto(s.url(orderId!));
      const driver = page.getByRole('combobox', { name: 'נהג' });
      await expect(driver).toBeVisible({ timeout: 30_000 });
      // после загрузки — реальный список (מה רצוי: сообщение только если водителей нет)
      await expect(driver.getByRole('option', { name: 'יוסי הנהג' })).toHaveCount(1, { timeout: 30_000 });
      expect(hits.n, 'запрос списка водителей перехвачен и задержан (иначе проверка не имеет смысла)').toBeGreaterThan(0);
      expect(await seen(page), `«${NO_DRIVERS}» появлялось во время загрузки`).toBe(false);
      await expect(page.getByText(NO_DRIVERS)).toHaveCount(0);
    });

    test(`${s.name}: אין נהגים באמת (תשובה ריקה) — ההודעה מוצגת אחרי הטעינה #a8bdcb @desktop @prod-safe`, async ({ page }) => {
      test.skip(!orderId, 'нет утверждённого заказа клиента «test» с адресом');
      await page.route(DRIVERS_API, (route) => route.fulfill({ status: 200, contentType: 'application/json', body: '[]' }));
      await page.goto(s.url(orderId!));
      await expect(page.getByText(NO_DRIVERS).first()).toBeVisible({ timeout: 30_000 });
      await expect(page.getByText(/הוסיפו עובד עם תפקיד «נהג חלוקה» במסך הצוות/).first()).toBeVisible();
    });
  }
});
